/**
 * prism-memory.ts — M3-A 持久大脑存取接口
 *
 * 配置驱动的分类注册表 + 文件系统持久化（md 条目，人可读可手改）。
 * 注入(M3-B) / 沉淀(M3-C) 不在本模块，仅提供 load / append 原语。
 */
import * as fs from 'fs';
import * as path from 'path';
import { fileURLToPath } from 'url';

export type MemoryCategory = string;

export interface MemoryEntry {
  id: string;
  category: MemoryCategory;
  content: string;
  source?: string;
  createdAt: string;
  [k: string]: unknown;
}

export interface MemoryCategoryConfig {
  name: MemoryCategory;
  dir: string;
  enabled: boolean;
  description: string;
}

/** 分类注册表：加新类只改这里，不动读写逻辑 */
export const MEMORY_CATEGORIES: MemoryCategoryConfig[] = [
  {
    name: 'priors',
    dir: 'priors',
    enabled: true,
    description: '先验知识（人工种子，如 Unity/AOE 分析知识）',
  },
  {
    name: 'knowledge',
    dir: 'knowledge',
    enabled: true,
    description: '知识回路（run 确认的业务归因 findings）',
  },
  {
    name: 'capabilities',
    dir: 'capabilities',
    enabled: true,
    description: '能力回路（DataRequest 池高频项）',
  },
  {
    name: 'lessons',
    dir: 'lessons',
    enabled: true,
    description: '质量回路（对错教训，依赖金标 BK-4）',
  },
];

export interface LoadMemoryOptions {
  /** 只加载指定分类；未指定时加载所有 enabled 分类 */
  categories?: MemoryCategory[];
  /** 覆盖默认存储根目录（单测用） */
  root?: string;
}

export interface AppendMemoryOptions {
  /** 覆盖默认存储根目录（单测用） */
  root?: string;
}

interface MemoryIndex {
  version: number;
  updatedAt: string;
  categories: Record<string, { count: number; lastUpdated: string | null }>;
}

const MODULE_DIR = path.dirname(fileURLToPath(import.meta.url));
const DEFAULT_MEMORY_ROOT = path.join(MODULE_DIR, 'prism-memory');

function getMemoryRoot(opts?: { root?: string }): string {
  return opts?.root ?? DEFAULT_MEMORY_ROOT;
}

function getCategoryConfig(name: MemoryCategory): MemoryCategoryConfig | undefined {
  return MEMORY_CATEGORIES.find((c) => c.name === name);
}

function categoryDir(root: string, config: MemoryCategoryConfig): string {
  return path.join(root, config.dir);
}

function ensureCategoryDir(root: string, config: MemoryCategoryConfig): void {
  const dir = categoryDir(root, config);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

function parseFrontmatter(raw: string): { meta: Record<string, unknown>; content: string } {
  const trimmed = raw.replace(/^\uFEFF/, '').trimStart();
  if (!trimmed.startsWith('---')) {
    return { meta: {}, content: trimmed };
  }
  const end = trimmed.indexOf('---', 3);
  if (end === -1) {
    return { meta: {}, content: trimmed };
  }
  const header = trimmed.slice(3, end).trim();
  const content = trimmed.slice(end + 3).trimStart();
  const meta: Record<string, unknown> = {};
  for (const line of header.split('\n')) {
    const colon = line.indexOf(':');
    if (colon === -1) continue;
    const key = line.slice(0, colon).trim();
    let value: unknown = line.slice(colon + 1).trim();
    if (typeof value === 'string' && value.startsWith('"') && value.endsWith('"')) {
      value = value.slice(1, -1);
    }
    meta[key] = value;
  }
  return { meta, content };
}

function serializeEntry(entry: MemoryEntry): string {
  const lines = [
    '---',
    `id: ${entry.id}`,
    `category: ${entry.category}`,
    `createdAt: ${entry.createdAt}`,
  ];
  if (entry.source) {
    lines.push(`source: ${entry.source}`);
  }
  for (const [key, value] of Object.entries(entry)) {
    if (['id', 'category', 'content', 'createdAt', 'source'].includes(key)) continue;
    if (value === undefined) continue;
    lines.push(`${key}: ${JSON.stringify(value)}`);
  }
  lines.push('---', '', entry.content);
  return lines.join('\n');
}

function entryFromFile(category: MemoryCategory, filePath: string): MemoryEntry | null {
  try {
    const raw = fs.readFileSync(filePath, 'utf8');
    const { meta, content } = parseFrontmatter(raw);
    const id = String(meta.id ?? path.basename(filePath, '.md'));
    const createdAt = String(meta.createdAt ?? new Date(0).toISOString());
    const source = meta.source !== undefined ? String(meta.source) : undefined;
    const entry: MemoryEntry = {
      id,
      category: String(meta.category ?? category),
      content,
      createdAt,
    };
    if (source) entry.source = source;
    for (const [key, value] of Object.entries(meta)) {
      if (['id', 'category', 'createdAt', 'source'].includes(key)) continue;
      entry[key] = value;
    }
    return entry;
  } catch {
    return null;
  }
}

function loadEntriesForCategory(
  root: string,
  config: MemoryCategoryConfig,
): MemoryEntry[] {
  const dir = categoryDir(root, config);
  if (!fs.existsSync(dir)) {
    return [];
  }
  const entries: MemoryEntry[] = [];
  for (const name of fs.readdirSync(dir)) {
    if (!name.endsWith('.md') || name === 'README.md') continue;
    const filePath = path.join(dir, name);
    if (!fs.statSync(filePath).isFile()) continue;
    const entry = entryFromFile(config.name, filePath);
    if (entry) entries.push(entry);
  }
  entries.sort((a, b) => a.createdAt.localeCompare(b.createdAt));
  return entries;
}

function readIndex(root: string): MemoryIndex {
  const indexPath = path.join(root, 'index.json');
  if (!fs.existsSync(indexPath)) {
    return buildIndexFromDisk(root);
  }
  try {
    const parsed = JSON.parse(fs.readFileSync(indexPath, 'utf8')) as MemoryIndex;
    return parsed;
  } catch {
    return buildIndexFromDisk(root);
  }
}

function buildIndexFromDisk(root: string): MemoryIndex {
  const categories: MemoryIndex['categories'] = {};
  for (const config of MEMORY_CATEGORIES) {
    const entries = loadEntriesForCategory(root, config);
    const lastUpdated =
      entries.length > 0 ? entries[entries.length - 1]!.createdAt : null;
    categories[config.name] = { count: entries.length, lastUpdated };
  }
  return {
    version: 1,
    updatedAt: new Date().toISOString(),
    categories,
  };
}

function writeIndex(root: string): void {
  const index = buildIndexFromDisk(root);
  index.updatedAt = new Date().toISOString();
  const indexPath = path.join(root, 'index.json');
  fs.writeFileSync(indexPath, JSON.stringify(index, null, 2) + '\n', 'utf8');
}

function resolveCategoriesToLoad(opts?: LoadMemoryOptions): MemoryCategoryConfig[] {
  const requested = opts?.categories;
  if (requested && requested.length > 0) {
    return requested
      .map((name) => getCategoryConfig(name))
      .filter((c): c is MemoryCategoryConfig => c !== undefined);
  }
  return MEMORY_CATEGORIES.filter((c) => c.enabled);
}

/** 读大脑；可按分类筛选、可只读启用的分类 */
export function loadMemory(opts?: LoadMemoryOptions): {
  entries: MemoryEntry[];
  byCategory: Record<string, MemoryEntry[]>;
} {
  const root = getMemoryRoot(opts);
  const configs = resolveCategoriesToLoad(opts);
  const byCategory: Record<string, MemoryEntry[]> = {};
  const entries: MemoryEntry[] = [];

  for (const config of configs) {
    const catEntries = loadEntriesForCategory(root, config);
    byCategory[config.name] = catEntries;
    entries.push(...catEntries);
  }

  return { entries, byCategory };
}

/** 追加一条并持久化 */
export function appendMemory(
  category: MemoryCategory,
  entry: Omit<MemoryEntry, 'category' | 'createdAt'> & { createdAt?: string },
  opts?: AppendMemoryOptions,
): MemoryEntry {
  const config = getCategoryConfig(category);
  if (!config) {
    throw new Error(`Unknown memory category: ${category}`);
  }

  const root = getMemoryRoot(opts);
  ensureCategoryDir(root, config);

  const fullEntry: MemoryEntry = {
    ...entry,
    category,
    createdAt: entry.createdAt ?? new Date().toISOString(),
  };

  const safeId = fullEntry.id.replace(/[^a-zA-Z0-9._-]/g, '_');
  const filePath = path.join(categoryDir(root, config), `${safeId}.md`);
  fs.writeFileSync(filePath, serializeEntry(fullEntry), 'utf8');
  writeIndex(root);

  return fullEntry;
}

/** 读取 index.json 概览（缺文件时从磁盘重建，不抛错） */
export function loadMemoryIndex(opts?: { root?: string }): MemoryIndex {
  const root = getMemoryRoot(opts);
  return readIndex(root);
}

/**
 * prism-memory.test.ts — M3-A 持久大脑存取单测
 *
 * Plain tsx script (no test runner). Run from web/ directory:
 *   npx tsx server/prism/prism-memory.test.ts
 */

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { fileURLToPath } from 'url';
import {
  MEMORY_CATEGORIES,
  appendMemory,
  loadMemory,
  loadMemoryIndex,
} from './prism-memory.js';

let passCount = 0;
let failCount = 0;

function assert(condition: boolean, label: string, detail?: unknown): void {
  if (condition) {
    console.log(`  PASS: ${label}`);
    passCount++;
  } else {
    console.log(`  FAIL: ${label}${detail !== undefined ? ' — ' + JSON.stringify(detail) : ''}`);
    failCount++;
  }
}

function makeTempRoot(): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'prism-memory-test-'));
}

function rmTempRoot(dir: string): void {
  fs.rmSync(dir, { recursive: true, force: true });
}

// ─────────────────────────── 1. append → load 读回 ─────────────────

console.log('\n[1] appendMemory then loadMemory read-back');
{
  const root = makeTempRoot();
  try {
    const saved = appendMemory(
      'knowledge',
      { id: 'k1', content: 'GC.Collect 70ms 卡顿由 LuaMgr 帧尾触发', source: 'test-run' },
      { root },
    );
    assert(saved.id === 'k1', 'append returns id k1');
    assert(saved.category === 'knowledge', 'append sets category knowledge');

    const loaded = loadMemory({ root });
    const k1 = loaded.byCategory.knowledge?.find((e) => e.id === 'k1');
    assert(k1 !== undefined, 'loadMemory finds k1 in knowledge');
    assert(
      k1?.content.includes('GC.Collect 70ms'),
      'loaded content matches append',
      k1?.content,
    );
    assert(k1?.source === 'test-run', 'loaded source preserved', k1?.source);
  } finally {
    rmTempRoot(root);
  }
}

// ─────────────────────────── 2. 按分类筛选 ───────────────────────────

console.log('\n[2] loadMemory category filter');
{
  const root = makeTempRoot();
  try {
    appendMemory('knowledge', { id: 'k2', content: 'knowledge only' }, { root });
    appendMemory('lessons', { id: 'l1', content: 'lesson only' }, { root });

    const knowledgeOnly = loadMemory({ categories: ['knowledge'], root });
    assert(
      (knowledgeOnly.byCategory.knowledge?.length ?? 0) === 1,
      'filter knowledge returns 1 entry',
      knowledgeOnly.byCategory,
    );
    assert(
      knowledgeOnly.byCategory.lessons === undefined,
      'filter knowledge excludes lessons key',
      knowledgeOnly.byCategory,
    );
    assert(
      knowledgeOnly.entries.every((e) => e.category === 'knowledge'),
      'all entries are knowledge category',
      knowledgeOnly.entries,
    );
  } finally {
    rmTempRoot(root);
  }
}

// ─────────────────────────── 3. 空/缺分类不报错 ─────────────────────

console.log('\n[3] empty / missing category does not throw');
{
  const root = makeTempRoot();
  try {
    let threw = false;
    try {
      const empty = loadMemory({ root });
      assert(empty.entries.length === 0, 'empty root returns zero entries', empty.entries);
      assert(
        Object.keys(empty.byCategory).length === MEMORY_CATEGORIES.filter((c) => c.enabled).length,
        'empty root still has enabled category keys',
        Object.keys(empty.byCategory),
      );
    } catch {
      threw = true;
    }
    assert(!threw, 'loadMemory on empty root does not throw');

    const unknown = loadMemory({ categories: ['nonexistent-cat'], root });
    assert(unknown.entries.length === 0, 'unknown category filter returns empty', unknown.entries);
    assert(
      Object.keys(unknown.byCategory).length === 0,
      'unknown category filter has no byCategory keys',
      unknown.byCategory,
    );
  } finally {
    rmTempRoot(root);
  }
}

// ─────────────────────────── 4. 可插拔：只加载 priors ─────────────────

console.log('\n[4] loadMemory({categories:["priors"]}) only returns priors');
{
  const defaultRoot = path.join(path.dirname(fileURLToPath(import.meta.url)), 'prism-memory');
  const priorsOnly = loadMemory({ categories: ['priors'] });
  assert(priorsOnly.entries.length >= 2, 'priors has at least 2 seed refs', priorsOnly.entries.length);
  assert(
    priorsOnly.entries.every((e) => e.category === 'priors'),
    'all entries are priors',
    priorsOnly.entries.map((e) => e.category),
  );
  assert(
    priorsOnly.byCategory.knowledge === undefined,
    'priors-only load excludes knowledge',
    Object.keys(priorsOnly.byCategory),
  );
  assert(
    priorsOnly.byCategory.capabilities === undefined,
    'priors-only load excludes capabilities',
    Object.keys(priorsOnly.byCategory),
  );

  const index = loadMemoryIndex();
  assert(index.categories.priors !== undefined, 'index lists priors', index.categories);
  assert(fs.existsSync(path.join(defaultRoot, 'index.json')), 'index.json exists on disk');
}

// ─────────────────────────── 5. 可扩展：注册表加测试分类 ─────────────

console.log('\n[5] extensibility — new category via MEMORY_CATEGORIES registry');
{
  const root = makeTempRoot();
  const testCategory = {
    name: 'test-ext',
    dir: 'test-ext',
    enabled: true,
    description: '单测临时分类',
  };
  MEMORY_CATEGORIES.push(testCategory);
  try {
    const saved = appendMemory('test-ext', { id: 'x1', content: 'extensible category works' }, { root });
    assert(saved.category === 'test-ext', 'append to new category succeeds');

    const loaded = loadMemory({ categories: ['test-ext'], root });
    assert(
      loaded.byCategory['test-ext']?.[0]?.id === 'x1',
      'load from new category works',
      loaded.byCategory['test-ext'],
    );

    const index = loadMemoryIndex({ root });
    assert(index.categories['test-ext']?.count === 1, 'index tracks new category', index.categories);
  } finally {
    MEMORY_CATEGORIES.pop();
    rmTempRoot(root);
  }
}

// ─────────────────────────── Summary ───────────────────────────────

console.log(`\n${'─'.repeat(50)}`);
console.log(`Results: ${passCount} PASS, ${failCount} FAIL`);
if (failCount > 0) {
  console.log('OVERALL: FAIL');
  process.exit(1);
} else {
  console.log('OVERALL: PASS');
  process.exit(0);
}

// 解析 CodeBuddy / Claude CLI 可执行路径 (Windows 下 npm 全局 bin 常不在 Node 服务 PATH 中)

import fs from 'fs';
import path from 'path';
import { execSync, spawn, type ChildProcess, type SpawnOptions } from 'child_process';
import type { CliProvider } from '../../shared/types.js';

function existsFile(p: string): boolean {
  try {
    return fs.existsSync(p);
  } catch {
    return false;
  }
}

/** Windows: %APPDATA%\\npm\\codebuddy.cmd */
function npmGlobalCmd(name: string): string | undefined {
  const appData = process.env.APPDATA;
  if (!appData) return undefined;
  const cmd = path.join(appData, 'npm', `${name}.cmd`);
  return existsFile(cmd) ? cmd : undefined;
}

function whereOnPath(name: string): string | undefined {
  try {
    const cmd = process.platform === 'win32' ? 'where.exe' : 'which';
    const out = execSync(`${cmd} ${name}`, { encoding: 'utf-8', windowsHide: true, timeout: 5000 }).trim();
    const line = out.split(/\r?\n/).find(l => l.trim())?.trim();
    return line && existsFile(line) ? line : undefined;
  } catch {
    return undefined;
  }
}

export function detectCliExecutable(provider: CliProvider): string | undefined {
  if (provider === 'mock') return undefined;

  const candidates: string[] = [];

  if (provider === 'codebuddy') {
    const npm = npmGlobalCmd('codebuddy');
    if (npm) candidates.push(npm);
    candidates.push('codebuddy');
  } else if (provider === 'claude') {
    const npm = npmGlobalCmd('claude');
    if (npm) candidates.push(npm);
    candidates.push('claude');
  }

  const found = whereOnPath(provider);
  if (found) candidates.unshift(found);

  for (const c of candidates) {
    if (c.includes('/') || c.includes('\\')) {
      if (existsFile(c)) return c;
    } else {
      const w = whereOnPath(c);
      if (w) return w;
    }
  }
  return undefined;
}

/** 配置路径 > 自动探测 > 命令名 (可能失败) */
export function resolveCliExecutable(
  provider: CliProvider,
  configuredPath?: string,
): { command: string; resolved: boolean } {
  if (provider === 'mock') return { command: 'mock', resolved: true };

  if (configuredPath && existsFile(configuredPath)) {
    return { command: configuredPath, resolved: true };
  }

  const detected = detectCliExecutable(provider);
  if (detected) return { command: detected, resolved: true };

  return { command: provider, resolved: false };
}

export function isCliAvailable(provider: CliProvider, configuredPath?: string): boolean {
  if (provider === 'mock') return true;
  return resolveCliExecutable(provider, configuredPath).resolved;
}

/** 上传/skill 默认 provider: 有 CodeBuddy 用 codebuddy，否则 mock */
export function defaultCliProvider(cliPaths?: Partial<Record<CliProvider, string>>): CliProvider {
  if (isCliAvailable('codebuddy', cliPaths?.codebuddy)) return 'codebuddy';
  if (isCliAvailable('claude', cliPaths?.claude)) return 'claude';
  return 'mock';
}

export function cliUnavailableHint(provider: CliProvider): string {
  if (provider === 'codebuddy') {
    return '未找到 CodeBuddy CLI。请在「设置」填写 codebuddy 路径（如 %APPDATA%\\npm\\codebuddy.cmd），或上传时选 Mock 模式。';
  }
  if (provider === 'claude') {
    return '未找到 Claude CLI。请在「设置」填写 claude 路径，或选 Mock 模式。';
  }
  return 'CLI 不可用';
}

/**
 * Windows: Node 服务进程 PATH 常缺 System32/Wbem，CodeBuddy 内部会调 reg/wmic 导致 skill 失败。
 * 合并 System32、Wbem、npm 全局 bin 与当前 PATH。
 */
export function buildCliSpawnEnv(base: NodeJS.ProcessEnv = process.env): NodeJS.ProcessEnv {
  const env = { ...base };
  if (process.platform !== 'win32') return env;

  const systemRoot = env.SystemRoot || env.WINDIR || 'C:\\Windows';
  const prepend = [
    path.join(systemRoot, 'System32'),
    path.join(systemRoot, 'System32', 'Wbem'),
    path.join(systemRoot, 'System32', 'WindowsPowerShell', 'v1.0'),
    env.APPDATA ? path.join(env.APPDATA, 'npm') : '',
    systemRoot,
  ].filter(p => p && existsFile(p));

  const seen = new Set<string>();
  const merged: string[] = [];
  for (const p of [...prepend, ...(env.PATH || env.Path || '').split(';')]) {
    const t = p.trim();
    if (!t || seen.has(t.toLowerCase())) continue;
    seen.add(t.toLowerCase());
    merged.push(t);
  }

  const pathStr = merged.join(';');
  env.PATH = pathStr;
  env.Path = pathStr;
  env.SystemRoot = systemRoot;
  env.WINDIR = systemRoot;
  const comspec = path.join(systemRoot, 'System32', 'cmd.exe');
  if (existsFile(comspec)) {
    env.COMSPEC = comspec;
  }
  return env;
}

/** Windows: 启动 CLI 并注入完整 PATH (System32 / PowerShell / npm) */
export function spawnCliProcess(
  cliCommand: string,
  args: string[],
  options: { cwd?: string; env?: NodeJS.ProcessEnv; windowsHide?: boolean; stdio?: SpawnOptions['stdio'] },
): ChildProcess {
  const env = buildCliSpawnEnv(options.env ?? process.env);
  return spawn(cliCommand, args, {
    cwd: options.cwd,
    env,
    windowsHide: options.windowsHide ?? true,
    stdio: options.stdio ?? 'pipe',
    shell: true,
  });
}

// ─────────────────────────────────────────────

/** ESM-safe __dirname equivalent */
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

/** Convert Windows backslash path to POSIX forward-slash path */
function toPosix(p: string): string {
  return p.replace(/\\/g, '/');
}

// NOTE: prompt is piped via stdin (see spawn below), NOT passed as `-p` arg.
// Windows .cmd wrappers truncate long multi-line prompts passed as positional
// args; `-p` with no value tells codebuddy/claude to read the prompt from stdin.
const CLI_PROVIDERS: Record<string, (prompt: string) => string[]> = {
  codebuddy: (_prompt) => [
    '-p',
    '--output-format', 'stream-json',
    '-y',
    '--allowedTools', 'Bash,Read,Write,Glob,Grep',
  ],
  claude: (_prompt) => [
    '-p',
    '--output-format', 'stream-json',
    '--allowedTools', 'Bash,Read,Write,Glob,Grep',
  ],
};

/**
 * Parse the command string inside a Bash tool_use input to extract
 * a Prism tools.cli.ts invocation, returning { toolName, argsJson }.
 * Returns null if this Bash call is not a tools.cli.ts invocation.
 */
function parseToolsCliCall(bashCommand: string): { toolName: string; argsJson: string } | null {
  // Matches: ... tools.cli.ts <toolName> '<jsonArgs>'
  // The JSON args may use single-quotes (shell) or be absent
  const re = /tools\.cli\.ts\s+(\w+)\s+'([^']+)'/;
  const m = bashCommand.match(re);
  if (m) return { toolName: m[1], argsJson: m[2] };

  // Also handle: tools.cli.ts <toolName> '<jsonArgs>' with double-quotes
  const re2 = /tools\.cli\.ts\s+(\w+)\s+"([^"]+)"/;
  const m2 = bashCommand.match(re2);
  if (m2) return { toolName: m2[1], argsJson: m2[2] };

  // Or no args: tools.cli.ts <toolName>
  const re3 = /tools\.cli\.ts\s+(\w+)\s*$/;
  const m3 = bashCommand.match(re3);
  if (m3) return { toolName: m3[1], argsJson: '{}' };

  return null;
}

/**
 * Parse a `tools.cli.ts batch '[{tool,args},...]'` command into its item list.
 * Returns null if this is not a batch call.
 */
function parseBatchCall(bashCommand: string): Array<{ tool: string; args?: Record<string, unknown> }> | null {
  const re = /tools\.cli\.ts\s+batch\s+'([\s\S]+?)'(?:\s|$|>)/;
  const re2 = /tools\.cli\.ts\s+batch\s+"([\s\S]+?)"(?:\s|$|>)/;
  const m = bashCommand.match(re) ?? bashCommand.match(re2);
  if (!m) return null;
  try {
    const arr = JSON.parse(m[1]);
    if (!Array.isArray(arr)) return null;
    return arr.map((x: { tool: string; args?: Record<string, unknown> }) => ({ tool: x.tool, args: x.args }));
  } catch {
    return null;
  }
}

/**
 * Extract the JSON array printed by a batch invocation from resultText.
 * The batch CLI prints `[{tool,args,ok,result},...]`. Returns the array or null.
 */
function extractBatchResults(text: string): unknown[] | null {
  if (!text) return null;
  const idx = text.indexOf('[');
  if (idx < 0) return null;
  let depth = 0, end = -1;

fs.mkdirSync(outputDir, { recursive: true });

const ledgerPath = path.join(outputDir, 'ledger.json');
const findingsPath = path.join(outputDir, 'findings.json');
const dataRequestsPath = path.join(outputDir, 'data-requests.json');
const verdictPath = path.join(outputDir, 'verdict.json');
const exploreResultPath = path.join(outputDir, 'explore-result.json');

// Read and substitute prompt template
const promptTemplatePath = path.join(__dirname, 'prompts', 'explore-prompt.txt');
if (!fs.existsSync(promptTemplatePath)) {
  return makeError(runId, ledgerPath, findingsPath, `Prompt template not found: ${promptTemplatePath}`);
}

let promptText = fs.readFileSync(promptTemplatePath, 'utf-8');
// Use POSIX (forward-slash) path for OUTPUT_DIR so the LLM's Write calls work cross-platform
const outputDirPosix = toPosix(outputDir);
promptText = promptText.replace(/\{\{RUN_ID\}\}/g, runId);
promptText = promptText.replace(/\{\{OUTPUT_DIR\}\}/g, outputDirPosix);
// F8: frame-budget verdict basis. Default 16.67ms (60fps) per aoe-watch-spec deviceTier default.
const frameBudgetMs = opts.frameBudgetMs ?? 16.67;
const targetFps = Math.round(1000 / frameBudgetMs);
promptText = promptText.replace(/\{\{FRAME_BUDGET_MS\}\}/g, String(frameBudgetMs));
promptText = promptText.replace(/\{\{TARGET_FPS\}\}/g, String(targetFps));

// Resolve CLI
const provider = opts.cliProvider ?? 'codebuddy';
const { command: cliCommand, resolved } = resolveCliExecutable(provider, config.cliPaths?.[provider]);

if (!resolved) {
  return makeError(runId, ledgerPath, findingsPath, cliUnavailableHint(provider));
}

const buildArgs = CLI_PROVIDERS[provider];
if (!buildArgs) {
  return makeError(runId, ledgerPath, findingsPath, `Unknown CLI provider: ${provider}`);
}
const args = buildArgs(promptText);

console.log(`[explore] Spawning ${provider} CLI (${cliCommand})...`);
console.log(`[explore] runId=${runId}, outputDir=${outputDirPosix}`);

const ledger: LedgerEntry[] = [];
let toolCallSeq = 0;
// Pending tool_use entries awaiting their tool_result (matched by position in stream order)
const pendingToolUses: LedgerEntry[] = [];

const timeoutMs = opts.timeoutMs ?? 20 * 60 * 1000;

return new Promise<ExploreRunResult>((resolve) => {
  let settled = false;
  let jsonBuffer = '';

  const child = spawnCliProcess(cliCommand, args, {
    cwd: config.skillProjectPath,
    env: process.env,
    windowsHide: true,
    stdio: 'pipe',
  });

  // Pipe the prompt via stdin (Windows .cmd wrappers truncate long prompts
  // passed as positional args; stdin avoids that trap). `-p` with no value
  // makes the CLI read the prompt from stdin.
  try {
    child.stdin?.write(promptText);
    child.stdin?.end();
  } catch (e: any) {
    console.error(`[explore] stdin write failed: ${e?.message || e}`);
  }

  const doResolve = (result: ExploreRunResult) => {
    if (!settled) {
      settled = true;
      resolve(result);
    }
  };

  const timeoutHandle = setTimeout(() => {
    if (child.exitCode === null) {
      child.kill('SIGTERM');
    }
    // Write whatever ledger we have so far
    writeLedger(ledgerPath, ledger);
    doResolve(makeError(runId, ledgerPath, findingsPath, `Exploration timed out after ${timeoutMs}ms`));
  }, timeoutMs);

  child.stdout?.on('data', (data: Buffer) => {
    jsonBuffer += data.toString();
    const lines = jsonBuffer.split('\n');
    jsonBuffer = lines.pop() || '';

    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed) continue;
      let event: Record<string, unknown>;
      try {
        event = JSON.parse(trimmed);
      } catch {
        // Non-JSON line — log it but continue
        console.log(`[explore:raw] ${trimmed.slice(0, 200)}`);
        continue;
      }

      handleExploreStreamEvent(event, ledger, pendingToolUses, (seq, name, input) => {
        toolCallSeq = seq;
        console.log(`[explore:tool #${seq}] ${name}: ${JSON.stringify(input).slice(0, 180)}`);
      });
    }
  });

  child.stderr?.on('data', (data: Buffer) => {
    const text = data.toString().trim();
    if (text) {
      console.error(`[explore:stderr] ${text.slice(0, 300)}`);
    }
  });

  child.on('error', (err) => {
    clearTimeout(timeoutHandle);
    writeLedger(ledgerPath, ledger);

  provider: CliProvider,
  onLog?: (line: string) => void,
): Promise<void> {
  const config = getConfig();
  const dest = path.join(workDir, 'performance-report.md');
  if (provider === 'mock') {
    fs.copyFileSync(enrichedPath, dest);
    return;
  }
  const { command, resolved } = resolveCliExecutable(provider, config.cliPaths?.[provider]);
  if (!resolved) throw new Error(cliUnavailableHint(provider));

  const prompt = buildCliPrompt(workDir, enrichedPath, config.skillProjectPath);
  fs.writeFileSync(path.join(workDir, 'single-cli-prompt.txt'), prompt, 'utf-8');
  const args = CLI_ARGS[provider] ?? CLI_ARGS.codebuddy;
  onLog?.(`[single] CLI 加厚 (${provider})…`);

  await new Promise<void>((resolve, reject) => {
    const child: ChildProcess = spawnCliProcess(command, args, {
      cwd: config.skillProjectPath,
      env: process.env,
      windowsHide: true,
      stdio: 'pipe',
    });
    const logs: string[] = [];
    try {
      child.stdin?.write(prompt);
      child.stdin?.end();
    } catch (e: any) {
      onLog?.(`[single] stdin: ${e.message}`);
    }
    child.stdout?.on('data', (d: Buffer) => {
      const t = d.toString().trim();
      if (t) { logs.push(t); onLog?.(`[cli] ${t.slice(0, 300)}`); }
    });
    child.stderr?.on('data', (d: Buffer) => {
      const t = d.toString().trim();
      if (t) onLog?.(`[stderr] ${t.slice(0, 300)}`);
    });
    child.on('error', reject);
    child.on('close', code => {
      fs.writeFileSync(path.join(workDir, 'single-cli.log'), logs.join('\n'), 'utf-8');
      if (code !== 0) reject(new Error(`CLI exit ${code}`));
      else if (!fs.existsSync(dest)) reject(new Error('CLI 未产出 performance-report.md'));
      else resolve();
    });
    setTimeout(() => {
      if (child.exitCode === null) {
        child.kill('SIGTERM');
        reject(new Error('CLI 超时'));
      }
    }, 12 * 60 * 1000);
  });
}

