+
+  const timeoutMs = opts?.timeoutMs ?? 10 * 60 * 1000;
+
+  return new Promise<string>((resolve, reject) => {
+    let stdout = '';
+    let stderr = '';
+    let settled = false;
+
+    const child: ChildProcess = spawnCliProcess(command, args, {
+      cwd: config.skillProjectPath,
+      env: process.env,
+      windowsHide: true,
+      stdio: 'pipe',
+    });
